const OFFLINE_ARTISTS=[{"id": "lam", "year": "1943", "name": "威弗雷多·拉姆", "en": "Wifredo Lam", "dates": "1902—1982 · 古巴", "tags": ["复合形象", "文化记忆", "超现实主义"], "bio": "古巴现代主义艺术家。其作品将欧洲现代艺术的形式探索与加勒比文化、非洲裔文化经验相结合，以复合人物、植物与象征性形态创造独特的绘画语言。", "works": ["《丛林》（The Jungle，1942—1943）", "《永恒的存在》（The Eternal Presence，1944）"], "visual": "organic", "color": "#A8B7A1"}, {"id": "matta", "year": "1944", "name": "罗伯托·马塔", "en": "Roberto Matta", "dates": "1911—2002 · 智利", "tags": ["心理空间", "超现实主义", "动态结构"], "bio": "智利艺术家，探索心理空间、精神景观与形态之间的关系。他的作品常通过富于运动感的线条和不稳定空间，挑战传统绘画透视与实体的界限。", "works": ["《爱的眩晕》（The Vertigo of Eros，1944）"], "visual": "curve", "color": "#B4A7C8"}, {"id": "vigas", "year": "1951", "name": "奥斯瓦尔多·维加斯", "en": "Oswaldo Vigas", "dates": "1923—2014 · 委内瑞拉", "tags": ["神话象征", "有机形态", "具象与抽象"], "bio": "委内瑞拉现代主义艺术家。维加斯长期探索抽象与具象的边界，将神话意象、人物轮廓与文化记忆转化为充满张力的有机形态。广东美术馆的维加斯回顾展是本项目的初始研究来源。", "works": ["《小女巫》（Bruja infante，1951）", "《思源》（Ancestral，1976）"], "visual": "organic", "color": "#E07A6A"}, {"id": "soto", "year": "1955", "name": "赫苏斯·拉斐尔·索托", "en": "Jesús Rafael Soto", "dates": "1923—2005 · 委内瑞拉", "tags": ["动态艺术", "视错觉", "观众参与"], "bio": "委内瑞拉动态与光学艺术的重要实践者。索托通过重复线条、透明层次和观看位置的变化，让艺术作品从静态对象发展为观众能够感知和参与的空间经验。", "works": ["《可穿行装置》（Penetrables，系列）"], "visual": "rect", "color": "#7A8FA3"}, {"id": "herrera", "year": "1959", "name": "卡门·埃雷拉", "en": "Carmen Herrera", "dates": "1915—2022 · 古巴 / 美国", "tags": ["几何抽象", "硬边绘画", "极简构图"], "bio": "古巴裔美国艺术家，以锐利的几何边界、简约色彩关系和精确的空间切分著称。作品强调视觉关系本身，并通过有限元素形成鲜明构图张力。", "works": ["《白与绿》（Blanco y Verde，系列）"], "visual": "triangle", "color": "#A8B7A1"}, {"id": "cruz", "year": "1959", "name": "卡洛斯·克鲁兹-迭斯", "en": "Carlos Cruz-Diez", "dates": "1923—2019 · 委内瑞拉", "tags": ["色彩感知", "光学艺术", "变化与观看"], "bio": "委内瑞拉艺术家，重点研究色彩如何因观看位置、光线和材料条件而变化。他将颜色从固定的画面属性转变为随观众感知改变的动态经验。", "works": ["《物理色彩》（Physichromies，1959年起）"], "visual": "rect", "color": "#DAB875"}];
