const __visuals = (()=>{
const PALETTE=['#E07A6A','#A8B7A1','#B4A7C8','#DAB875','#7A8FA3','#2C2C2C'];
const HUES={red:'#E07A6A',yellow:'#DAB875',green:'#A8B7A1',blue:'#7A8FA3',purple:'#B4A7C8'};
const SHAPES={circle:'圆形',rect:'矩形',triangle:'三角形',organic:'有机形态',curve:'曲线',arrow:'右箭头'};
function hash(s){let n=0;for(const c of String(s))n=((n*31+c.charCodeAt(0))>>>0);return n;}
function pathFor(type,a=35,seed=3){const t=a/100,shift=Math.sin(seed*3.1)*t*25;if(type==='circle')return `<path d="M ${-50-shift} 0 C ${-50-shift} ${-60+shift},${56+shift} ${-53-shift},${55+shift} 0 C ${52-shift} ${55+shift},${-54+shift} ${60-shift},${-50-shift} 0Z"/>`;if(type==='rect')return `<path d="M ${-53-shift} ${-52+shift} L ${53+shift} ${-52-shift} L ${53-shift} ${52+shift} L ${-53+shift} ${52-shift}Z"/>`;if(type==='triangle')return `<path d="M ${shift} ${-65-shift} L ${66+shift} ${55+shift} L ${-66-shift} ${55-shift}Z"/>`;if(type==='organic2')return `<path d="M ${-45+shift} -52 C -4 -91 62 -73 55 -28 C 101 18 48 69 11 57 C -49 100 -90 22 ${-45+shift} -52Z"/>`;if(type==='organic3')return `<path d="M -54 -12 Q -92 -69 -24 -55 Q 18 -92 44 -40 Q 100 -39 66 15 Q 74 81 18 63 Q -32 91 -53 39 Q -85 7 -54 -12Z"/>`;if(type==='blob'){let points=[];for(let i=0;i<12;i++){const ang=i*Math.PI/6;const radius=43+18*Math.sin(seed*2.71+i*1.94)+12*t*Math.cos(i*3+seed);points.push([Math.cos(ang)*radius,Math.sin(ang)*radius])}let d=points.map((p,i)=>`${i===0?'M':'L'} ${p[0].toFixed(2)} ${p[1].toFixed(2)}`).join(' ');return `<path d="${d} Z" stroke-linejoin="round"/>`};if(type==='curve2')return `<path d="M -80 0 C -58 -85 -25 82 0 0 S 56 -82 80 0" fill="none" stroke-width="12" stroke-linecap="round"/>`;if(type==='curve3'){const v=Math.sin(seed*2.7)*40;return `<path d="M -85 ${v*.4} Q -55 ${-70+v} -25 ${18-v} T 25 ${-15+v} Q 50 ${75-v} 85 ${-20-v*.3}" fill="none" stroke-width="12" stroke-linecap="round"/>`};if(type==='curve')return `<path d="M -76 40 Q ${-33+shift} ${-75-shift} 8 -24 T 76 ${28+shift}" fill="none" stroke-width="13" stroke-linecap="round"/>`;if(type==='arrow')return `<path d="M -85 -12 H 32 V -36 L 88 0 L32 36 V 12 H -85 Z"/>`;return `<path d="M ${-50+shift} -57 Q ${12-shift} -86 ${44+shift} -35 Q 90 ${-9+shift} 58 39 Q ${24-shift} 89 -30 54 Q -79 24 ${-50+shift} -57Z"/>`}
function glyph(type,color,x,y,scale=1,rotate=0,a=20,seed=3,extra=''){return `<g transform="translate(${x} ${y}) rotate(${rotate}) scale(${scale})" fill="${color}" stroke="#2C2C2C" stroke-width="${Math.max(1.5,2.8-a*.01)}" stroke-linejoin="round" ${extra}>${pathFor(type,a,seed)}</g>`}
function studySVG(seed=1,colors=PALETTE,form='organic'){const random=n=>((Math.sin(seed*91.7+n*12.989)*43758.5453)%1+1)%1;return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 370" preserveAspectRatio="xMidYMid meet"><rect width="600" height="370" fill="#EEE6D8"/>${glyph(form,colors[0],210+random(1)*35,175,1.25,random(2)*45,40,seed)}${glyph('rect',colors[1]||PALETTE[1],380,205,.95,-28,20,seed+4)}${glyph('triangle',colors[2]||PALETTE[2],300,110,.8,18,28,seed+2)}${glyph('circle',colors[3]||PALETTE[3],135,265,.48,0,20,seed+7)}<path d="M50 270 Q225 ${-20+random(4)*120} 540 220 M76 90 Q300 350 550 50" stroke="#2C2C2C" stroke-width="5" fill="none" opacity=".76"/><path d="M360 316H552l-27-27m27 27l-27 27" fill="none" stroke="#7A8FA3" stroke-width="6" stroke-linecap="round"/></svg>`}
function iconSVG(seed,kind,color){return studySVG(seed,[color,'#A8B7A1','#B4A7C8','#DAB875'],kind)}

return {PALETTE,HUES,SHAPES,hash,pathFor,glyph,studySVG,iconSVG};
})();
const {PALETTE,HUES,SHAPES,hash,pathFor,glyph,studySVG,iconSVG}=__visuals;
const __timeline = (()=>{
let artists=[],current=2;const q=x=>document.querySelector(x);
function initTimeline(data){artists=data;const nodes=q('#timelineNodes');nodes.innerHTML=artists.map((a,i)=>`<button data-artist="${i}"><span class="node-year">${a.year}</span><span class="node-label">${a.name}</span></button>`).join('');nodes.addEventListener('click',e=>{const b=e.target.closest('[data-artist]');if(b)showArtist(+b.dataset.artist)});q('#artistDetail').addEventListener('click',()=>openArtist(current));showArtist(current)}
function showArtist(i){current=i;const a=artists[i];q('#artistNumber').textContent=`ARTIST ${String(i+1).padStart(2,'0')} / ${String(artists.length).padStart(2,'0')}`;q('#artistName').textContent=a.name;q('#artistEnglish').textContent=a.en.toUpperCase();q('#artistDates').textContent=a.dates;q('#artistBio').textContent=a.bio;q('#artistTags').innerHTML=a.tags.map(t=>`<span class="chip">${t}</span>`).join('');q('#artistWorks').innerHTML=`<ul>${a.works.map(t=>`<li>${t}</li>`).join('')}</ul>`;q('#artistVisual').innerHTML=iconSVG(i+1,a.visual,a.color);document.querySelectorAll('[data-artist]').forEach((b,n)=>b.classList.toggle('selected',i===n))}
function openArtist(i){const a=artists[i],dialog=q('#detailDialog');q('#dialogContent').innerHTML=`<div class="detail-inner"><div class="eyebrow">ARTIST ARCHIVE / ${a.year}</div><h2>${a.name}</h2><div class="english">${a.en.toUpperCase()}</div><p>${a.dates}</p>${iconSVG(i+1,a.visual,a.color)}<p>${a.bio}</p><div class="eyebrow">代表作研究线索</div><ul>${a.works.map(t=>`<li>${t}</li>`).join('')}</ul><p class="detail-disclaimer">插图为项目原创程序化构图示意，不是艺术家的真实作品。正式展品须单独替换有来源与使用许可的图片。</p></div>`;dialog.showModal()}
function artistById(id){return artists.find(a=>a.id===id)}

return {initTimeline,showArtist,openArtist,artistById};
})();
const {initTimeline,showArtist,openArtist,artistById}=__timeline;
const __gallery = (()=>{
let works=[],hue='all',shape='all';const q=s=>document.querySelector(s);let onPrefs=()=>{};
function initGallery(data,callback){works=data;onPrefs=callback;const hf=q('#hueFilter');hf.innerHTML=[['all','全部'],...Object.entries(HUES)].map(([id,c])=>id==='all'?`<button class="hue-option" style="--swatch:linear-gradient(135deg,#E07A6A 0 25%,#A8B7A1 25% 50%,#B4A7C8 50% 75%,#7A8FA3 75%)" data-hue="all" aria-label="全部色相" title="全部色相"></button>`:`<button class="hue-option" style="--swatch:${c}" data-hue="${id}" aria-label="${id}" title="${id}"></button>`).join('');q('#shapeFilter').innerHTML=[['all','全部'],...Object.entries(SHAPES).filter(([id])=>['circle','rect','triangle','organic'].includes(id))].map(([id,label])=>`<button data-shape="${id}">${label}</button>`).join('');hf.addEventListener('click',e=>{const b=e.target.closest('[data-hue]');if(b){hue=b.dataset.hue;render()}});q('#shapeFilter').addEventListener('click',e=>{const b=e.target.closest('[data-shape]');if(b){shape=b.dataset.shape;render()}});q('#resetFilters').addEventListener('click',()=>{hue='all';shape='all';render()});q('#galleryGrid').addEventListener('click',e=>{const btn=e.target.closest('[data-work]');if(btn)openStudy(works.find(w=>w.id===btn.dataset.work))});render()}
function setFilters(nextHue,nextShape){hue=nextHue in HUES?nextHue:'all';shape=nextShape in SHAPES?nextShape:'all';render()}
function render(){document.querySelectorAll('[data-hue]').forEach(b=>b.classList.toggle('active',b.dataset.hue===hue));document.querySelectorAll('[data-shape]').forEach(b=>b.classList.toggle('active',b.dataset.shape===shape));const list=works.filter(w=>(hue==='all'||w.hues.includes(hue))&&(shape==='all'||w.shapes.includes(shape)));q('#resultCount').textContent=` / ${list.length} WORKS`;q('#filterLabel').textContent=`${hue==='all'?'全部色相':hue} × ${shape==='all'?'全部形状':SHAPES[shape]}`;q('#galleryGrid').innerHTML=list.length?list.map(w=>{const a=artistById(w.artistId);const colors=[HUES[w.hues[0]],HUES[w.hues[1]],'#B4A7C8','#DAB875'];return `<button class="gallery-card" data-work="${w.id}"><div class="thumb">${studySVG(w.seed,colors,w.shapes[0])}</div><strong>${w.title}</strong><small>${w.titleEn||''} · ${w.year||''}</small><small>${a?.name||''} · 图像占位示意</small></button>`}).join(''):'<p>暂无完全匹配的研究示意，尝试调整一个筛选条件。</p>';onPrefs(hue,shape)}
function openStudy(w){const a=artistById(w.artistId),dialog=q('#detailDialog');q('#dialogContent').innerHTML=`<div class="detail-inner"><div class="eyebrow">ARTWORK INDEX / ${w.id.toUpperCase()}</div><h2>${w.title}</h2><p>${w.titleEn||''} · ${w.year||''}</p>${studySVG(w.seed,[HUES[w.hues[0]],HUES[w.hues[1]],'#B4A7C8','#DAB875'],w.shapes[0])}<p>参考研究对象：${a?.name||''}。形式标签：${w.shapes.map(x=>SHAPES[x]).join('、')}；色相标签：${w.hues.join('、')}。</p><p class="detail-disclaimer">本图为代码生成的原创视觉研究素材，不是所列艺术家的真实作品，也不应当被标为其代表作。</p></div>`;dialog.showModal()}

return {initGallery,setFilters};
})();
const {initGallery,setFilters}=__gallery;
const __editor = (()=>{
const q=s=>document.querySelector(s),NS='http://www.w3.org/2000/svg';let shapes=[],selected=null,abstraction=35,order=20,history=[],position=-1,seed=0,drag=null;
const clone=x=>JSON.parse(JSON.stringify(x));const node=(name,attrs={})=>{let n=document.createElementNS(NS,name);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));return n};
function save(){history=history.slice(0,position+1);history.push(clone({shapes,abstraction,order}));if(history.length>40)history.shift();position=history.length-1;buttons()}
function buttons(){q('#undoBtn').disabled=position<=0;q('#redoBtn').disabled=position>=history.length-1;q('#elementCount').textContent=`${shapes.length} ELEMENTS`}
function current(){return shapes.find(s=>s.id===selected)}
function draw(){let layer=q('#artLayers');layer.replaceChildren();shapes.forEach((s,i)=>{const offset=order/100;let ox=Math.sin(s.seed*7.31)*offset*58,oy=Math.cos(s.seed*4.21)*offset*47,rot=s.rotation+Math.sin(s.seed*2)*offset*36;const g=node('g',{'data-id':s.id,transform:`translate(${s.x+ox} ${s.y+oy}) rotate(${rot}) scale(${s.scale})`,fill:s.color,opacity:s.opacity??1,stroke:s.outline?s.strokeColor:'none','stroke-width':s.outline?s.strokeWidth:0,'stroke-linejoin':'round',class:s.id===selected?'selected':''});const pathMarkup=pathFor(s.type,abstraction,s.seed);let sub=node('g');sub.innerHTML=pathMarkup;g.append(...sub.children);if(s.type.startsWith('curve')){g.querySelector('path').setAttribute('stroke',s.color);g.querySelector('path').setAttribute('stroke-width','12');}layer.append(g)});buttons();let s=current();q('#selectedInfo').textContent=s?`当前元素：${s.type} · ${shapes.indexOf(s)+1}/${shapes.length}`:'点击画布内元素进行编辑';q('#scaleSlider').disabled=q('#rotateSlider').disabled=q('#opacitySlider').disabled=q('#strokeToggle').disabled=q('#strokeColor').disabled=q('#strokeWidth').disabled=!s;if(document.activeElement!==q('#scaleSlider'))q('#scaleSlider').value=s?Math.round(s.scale*100):100;if(document.activeElement!==q('#rotateSlider'))q('#rotateSlider').value=s?s.rotation:0;q('#scaleVal').textContent=`${s?Math.round(s.scale*100):100}%`;q('#rotateVal').textContent=`${s?s.rotation:0}°`;q('#opacitySlider').value=s?Math.round((s.opacity??1)*100):100;q('#opacityVal').textContent=`${s?Math.round((s.opacity??1)*100):100}%`;q('#strokeToggle').textContent=s?.outline?'关闭边框':'启用边框';q('#strokeVal').textContent=s?.outline?'已启用':'无';q('#strokeColor').value=s?.strokeColor||'#2C2C2C';q('#strokeWidth').value=String(s?.strokeWidth||3);document.querySelectorAll('[data-editor-color]').forEach(b=>b.classList.toggle('active',!!s&&b.dataset.editorColor===s.color))}
function add(type,color){if(shapes.length>=30){status('最多添加 30 个元素');return}seed++;const s={id:`shape_${Date.now()}_${seed}`,type,x:480+(seed%5-2)*65,y:305+(seed%3-1)*52,scale:1,rotation:seed*23%90-45,color:color||PALETTE[(seed-1)%5],opacity:1,outline:false,strokeColor:'#2C2C2C',strokeWidth:3,seed};shapes.push(s);selected=s.id;save();draw()}
function status(s){q('#status').textContent=s}
function coord(e){let svg=q('#artboard'),pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const matrix=svg.getScreenCTM();return matrix?pt.matrixTransform(matrix.inverse()):{x:0,y:0}}
function initEditor(){document.querySelectorAll('[data-add]').forEach(b=>b.addEventListener('click',()=>add(b.dataset.add)));q('#editorPalette').innerHTML=PALETTE.map(c=>`<button style="--dot:${c}" data-editor-color="${c}" aria-label="元素颜色 ${c}"></button>`).join('');q('#editorPalette').addEventListener('click',e=>{const b=e.target.closest('[data-editor-color]'),s=current();if(b&&s){s.color=b.dataset.editorColor;save();draw()}});
q('#opacitySlider').addEventListener('input',e=>{const s=current();if(!s)return;s.opacity=+e.target.value/100;q('#opacityVal').textContent=e.target.value+'%';draw()});q('#opacitySlider').addEventListener('change',()=>{if(current())save()});q('#strokeToggle').addEventListener('click',()=>{const s=current();if(!s)return;s.outline=!s.outline;save();draw()});q('#strokeColor').addEventListener('input',e=>{const s=current();if(!s)return;s.strokeColor=e.target.value;draw()});q('#strokeColor').addEventListener('change',()=>{if(current())save()});q('#strokeWidth').addEventListener('change',e=>{const s=current();if(!s)return;s.strokeWidth=+e.target.value;save();draw()});const svg=q('#artboard');svg.addEventListener('pointerdown',e=>{const target=e.target.closest('[data-id]');selected=target?.dataset.id||null;draw();if(target){drag={id:selected,start:coord(e),origin:{x:current().x,y:current().y},moved:false};try{svg.setPointerCapture(e.pointerId)}catch{}}});svg.addEventListener('pointermove',e=>{if(!drag)return;let s=shapes.find(x=>x.id===drag.id);if(!s)return;let p=coord(e);s.x=drag.origin.x+p.x-drag.start.x;s.y=drag.origin.y+p.y-drag.start.y;drag.moved=true;draw()});function end(){if(drag?.moved)save();drag=null}svg.addEventListener('pointerup',end);svg.addEventListener('pointercancel',end);
[['abstractSlider','abstractVal','abstraction'],['orderSlider','orderVal','order']].forEach(([id,out,key])=>{q('#'+id).addEventListener('input',e=>{if(key==='abstraction')abstraction=+e.target.value;else order=+e.target.value;q('#'+out).textContent=e.target.value+'%';draw()});q('#'+id).addEventListener('change',save)});[['scaleSlider','scaleVal','scale'],['rotateSlider','rotateVal','rotation']].forEach(([id,out,key])=>{q('#'+id).addEventListener('input',e=>{let s=current();if(!s)return;s[key]=key==='scale'?e.target.value/100:+e.target.value;q('#'+out).textContent=e.target.value+(key==='scale'?'%':'°');draw()});q('#'+id).addEventListener('change',save)});
q('#deleteShape').addEventListener('click',()=>{if(!current())return;shapes=shapes.filter(s=>s.id!==selected);selected=null;save();draw()});q('#layerUp').addEventListener('click',()=>layerMove(1));q('#layerDown').addEventListener('click',()=>layerMove(-1));q('#undoBtn').addEventListener('click',()=>restore(-1));q('#redoBtn').addEventListener('click',()=>restore(1));q('#clearBtn').addEventListener('click',()=>{if(!confirm('确定清空画布？'))return;shapes=[];selected=null;save();draw()});q('#randomBtn').addEventListener('click',()=>{shapes=[];selected=null;['organic2','blob','triangle','rect','curve3','arrow','organic3','curve2'].forEach((t,i)=>{seed++;shapes.push({id:`random_${Date.now()}_${seed}`,type:t,x:160+(i%3)*320+Math.random()*30,y:185+Math.floor(i/3)*270,scale:.8+Math.random()*.5,rotation:Math.round(Math.random()*90-45),color:PALETTE[i],opacity:.6+Math.random()*.4,outline:Math.random()>.5,strokeWidth:3,strokeColor:'#2C2C2C',seed})});save();draw();status('已生成随机构图')});q('#exportBtn').addEventListener('click',exportPNG);['organic','circle','triangle','rect','curve'].forEach((s,i)=>add(s));selected=null;draw()}
function layerMove(direction){let i=shapes.findIndex(s=>s.id===selected),j=i+direction;if(i<0||j<0||j>=shapes.length)return;[shapes[i],shapes[j]]=[shapes[j],shapes[i]];save();draw()}
function restore(direction){let to=position+direction;if(to<0||to>=history.length)return;position=to;({shapes,abstraction,order}=clone(history[position]));if(!current())selected=null;q('#abstractSlider').value=abstraction;q('#orderSlider').value=order;q('#abstractVal').textContent=abstraction+'%';q('#orderVal').textContent=order+'%';draw()}
function setEditorStartingPrefs(color,shape){if(!shapes.length)return;let s=shapes[0];if(color)s.color=color;if(['circle','rect','triangle','organic'].includes(shape))s.type=shape;save();draw()}
function exportPNG(){const original=q('#artboard');const svg=original.cloneNode(true);svg.setAttribute('width','2400');svg.setAttribute('height','1560');svg.querySelectorAll('.selected').forEach(n=>n.classList.remove('selected'));const source=new XMLSerializer().serializeToString(svg);const blob=new Blob([source],{type:'image/svg+xml;charset=utf-8'}),url=URL.createObjectURL(blob);const img=new Image();img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=2400;canvas.height=1560;const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,2400,1560);canvas.toBlob(result=>{if(!result){status('导出失败');return}const link=document.createElement('a');link.href=URL.createObjectURL(result);link.download='no-right-turn-artwork.png';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),2000);status('PNG 已生成 · 2400×1560')},'image/png');URL.revokeObjectURL(url)};img.onerror=()=>{status('导出失败，请重试');URL.revokeObjectURL(url)};img.src=url}

return {initEditor,setEditorStartingPrefs};
})();
const {initEditor,setEditorStartingPrefs}=__editor;
const __opening = (()=>{
function initOpening(){const video=document.getElementById('openingVideo'),fallback=document.getElementById('openingFallback'),sound=document.getElementById('videoSound'),skip=document.getElementById('skipVideo');let ended=false;function finish(){ended=true;video.pause();video.style.display='none';fallback.style.display='block';skip.textContent='重新播放 CG';sound.disabled=true}skip.addEventListener('click',()=>{if(ended){ended=false;video.currentTime=0;video.style.display='block';fallback.style.display='none';sound.disabled=false;skip.textContent='跳过 CG';video.play().catch(finish)}else finish()});video.addEventListener('ended',finish);video.addEventListener('error',finish);sound.addEventListener('click',()=>{video.muted=!video.muted;sound.textContent=video.muted?'开启声音':'静音'});video.style.display='block';fallback.style.display='none';video.addEventListener('canplay',()=>video.play().catch(finish),{once:true});video.load();return {stop:()=>video.pause(),resume:()=>{if(!ended&&video.style.display==='block')video.play().catch(()=>{})}}}
return {initOpening};
})();
const {initOpening}=__opening;
import {initTimeline} from './timeline.js';import {initGallery,setFilters} from './gallery.js';import {initEditor,setEditorStartingPrefs} from './editor.js';import {HUES} from './visuals.js';
const q=s=>document.querySelector(s);let openingPrefs={color:'#E07A6A',shape:'organic'},galleryPrefs={hue:'all',shape:'all'},opening,enteredLab=false;
function navigate(id){if(!document.getElementById(id))return;document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===id));document.querySelectorAll('[data-go]').forEach(b=>b.classList.toggle('active',b.dataset.go===id));if(id==='gallery'&&galleryPrefs.hue==='all'&&galleryPrefs.shape==='all'){const hue=Object.keys(HUES).find(h=>HUES[h]===openingPrefs.color)||'all';setFilters(hue,openingPrefs.shape)}if(id==='lab'&&!enteredLab){let h=galleryPrefs.hue,form=galleryPrefs.shape,color=HUES[h]||openingPrefs.color;setEditorStartingPrefs(color,form==='all'?openingPrefs.shape:form);enteredLab=true}if(id==='opening')opening?.resume();else opening?.stop();q('#status').textContent=`VIEW / ${id.toUpperCase()}`;window.location.hash=id}
async function start(){initTimeline(OFFLINE_ARTISTS);initGallery(OFFLINE_ARTWORKS,(hue,shape)=>galleryPrefs={hue,shape});initEditor();opening=initOpening((color,shape)=>openingPrefs={color,shape});document.addEventListener('click',e=>{const b=e.target.closest('[data-go]');if(b)navigate(b.dataset.go)});q('#closeDialog').addEventListener('click',()=>q('#detailDialog').close());q('#detailDialog').addEventListener('click',e=>{if(e.target===q('#detailDialog'))q('#detailDialog').close()});window.addEventListener('hashchange',()=>{const h=location.hash.slice(1);if(['opening','timeline','gallery','lab'].includes(h)&&!document.getElementById(h).classList.contains('active'))navigate(h)});navigate(['opening','timeline','gallery','lab'].includes(location.hash.slice(1))?location.hash.slice(1):'opening')}
start().catch(e=>{q('#status').textContent='加载失败：'+e.message;console.error(e)});
